def svg(name: str, size: int = 20, color: str = "currentColor") -> str:
    """أيقونة كـ SVG جاهزة للإدراج في HTML. اسم مجهول يُرجع فراغاً لا خطأً."""
    path = ICON_PATHS.get(name)
    if not path:
        return ""
    return (
        f'<svg xmlns="http://www.w3.org/2000/svg" width="{size}" height="{size}" '
        f'fill="{color}" viewBox="0 0 16 16" style="flex-shrink:0;">{path}</svg>'
    )
